cat > staking/src/lib.rs <<'EOF'
#![no_std]
use soroban_sdk::{
    contract, contracterror, contractimpl, contracttype, panic_with_error, token, Address, Env,
};

/// Ledgers per day at about 5 seconds per ledger.
const DAY_IN_LEDGERS: u32 = 17_280;
/// Extend a user's stake when less than 30 days of lifetime remain.
const TTL_THRESHOLD: u32 = 30 * DAY_IN_LEDGERS;
/// Extend the lifetime of a user's stake to 60 days.
const TTL_EXTEND_TO: u32 = 60 * DAY_IN_LEDGERS;

#[contracttype]
#[derive(Clone)]
pub enum DataKey {
    /// Address of the staked token (a Stellar Asset Contract). Instance storage.
    Token,
    /// Total amount staked by everyone. Instance storage.
    Total,
    /// Amount staked by one user. Persistent storage.
    Staked(Address),
}

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum Error {
    /// The amount must be greater than zero.
    InvalidAmount = 1,
    /// The user has less staked than the amount they asked to unstake.
    InsufficientStake = 2,
}

#[contract]
pub struct Staking;

fn token_client(env: &Env) -> token::TokenClient<'_> {
    let token: Address = env.storage().instance().get(&DataKey::Token).unwrap();
    token::TokenClient::new(env, &token)
}

fn read_staked(env: &Env, user: &Address) -> i128 {
    let key = DataKey::Staked(user.clone());
    if env.storage().persistent().has(&key) {
        env.storage().persistent().extend_ttl(&key, TTL_THRESHOLD, TTL_EXTEND_TO);
    }
    env.storage().persistent().get(&key).unwrap_or(0)
}

fn write_staked(env: &Env, user: &Address, amount: i128) {
    let key = DataKey::Staked(user.clone());
    env.storage().persistent().set(&key, &amount);
    env.storage().persistent().extend_ttl(&key, TTL_THRESHOLD, TTL_EXTEND_TO);
}

fn read_total(env: &Env) -> i128 {
    env.storage().instance().get(&DataKey::Total).unwrap_or(0)
}

fn write_total(env: &Env, amount: i128) {
    env.storage().instance().set(&DataKey::Total, &amount);
}

#[contractimpl]
impl Staking {
    /// Set the token to stake. `token` is the Stellar Asset Contract address (for XLM, the native
    /// asset's contract ID on the network being deployed to).
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        write_total(&env, 0);
    }

    /// Stake `amount` of the token from `user`. The user must authorize this call.
    pub fn stake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        token_client(&env).transfer(&user, &env.current_contract_address(), &amount);

        write_staked(&env, &user, read_staked(&env, &user) + amount);
        write_total(&env, read_total(&env) + amount);
    }

    /// Withdraw `amount` of the token back to `user`. The user must authorize this call and must
    /// have at least `amount` staked.
    pub fn unstake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        let staked = read_staked(&env, &user);
        if staked < amount {
            panic_with_error!(&env, Error::InsufficientStake);
        }

        write_staked(&env, &user, staked - amount);
        write_total(&env, read_total(&env) - amount);
        token_client(&env).transfer(&env.current_contract_address(), &user, &amount);
    }

    /// The amount `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        read_staked(&env, &user)
    }

    /// The amount staked by everyone.
    pub fn total_staked(env: Env) -> i128 {
        read_total(&env)
    }
}

mod test;
EOF
cat > staking/src/test.rs <<'EOF'
#![cfg(test)]

use super::*;
use soroban_sdk::{testutils::Address as _, Address, Env};

/// Deploys a fresh native-style Stellar Asset Contract and the staking contract, and mints
/// `balance` of the token to `user`.
fn setup(balance: i128) -> (Env, Address, Address, Address) {
    let env = Env::default();
    env.mock_all_auths();

    let admin = Address::generate(&env);
    let user = Address::generate(&env);
    let token_id = env.register_stellar_asset_contract_v2(admin).address();
    token::StellarAssetClient::new(&env, &token_id).mint(&user, &balance);

    let contract_id = env.register(Staking, (token_id.clone(),));
    (env, contract_id, token_id, user)
}

#[test]
fn stake_increases_user_and_total() {
    let (env, contract_id, _token_id, user) = setup(1_000);
    let client = StakingClient::new(&env, &contract_id);

    assert_eq!(client.staked(&user), 0);
    assert_eq!(client.total_staked(), 0);

    client.stake(&user, &400);
    assert_eq!(client.staked(&user), 400);
    assert_eq!(client.total_staked(), 400);

    client.stake(&user, &100);
    assert_eq!(client.staked(&user), 500);
    assert_eq!(client.total_staked(), 500);
}

#[test]
fn stake_moves_tokens_to_the_contract() {
    let (env, contract_id, token_id, user) = setup(1_000);
    let client = StakingClient::new(&env, &contract_id);
    let token = token::Client::new(&env, &token_id);

    client.stake(&user, &250);
    assert_eq!(token.balance(&user), 750);
    assert_eq!(token.balance(&contract_id), 250);
}

#[test]
fn unstake_returns_tokens_and_reduces_stake() {
    let (env, contract_id, token_id, user) = setup(1_000);
    let client = StakingClient::new(&env, &contract_id);
    let token = token::Client::new(&env, &token_id);

    client.stake(&user, &600);
    client.unstake(&user, &200);

    assert_eq!(client.staked(&user), 400);
    assert_eq!(client.total_staked(), 400);
    assert_eq!(token.balance(&user), 600);
    assert_eq!(token.balance(&contract_id), 400);
}

#[test]
fn unstake_everything() {
    let (env, contract_id, token_id, user) = setup(1_000);
    let client = StakingClient::new(&env, &contract_id);
    let token = token::Client::new(&env, &token_id);

    client.stake(&user, &300);
    client.unstake(&user, &300);

    assert_eq!(client.staked(&user), 0);
    assert_eq!(client.total_staked(), 0);
    assert_eq!(token.balance(&user), 1_000);
}

#[test]
fn unstake_more_than_staked_fails() {
    let (env, contract_id, token_id, user) = setup(1_000);
    let client = StakingClient::new(&env, &contract_id);
    let token = token::Client::new(&env, &token_id);

    client.stake(&user, &100);
    let result = client.try_unstake(&user, &101);
    assert_eq!(result, Err(Ok(Error::InsufficientStake)));

    // Nothing changed.
    assert_eq!(client.staked(&user), 100);
    assert_eq!(client.total_staked(), 100);
    assert_eq!(token.balance(&user), 900);
}

#[test]
fn unstake_without_any_stake_fails() {
    let (env, contract_id, _token_id, user) = setup(1_000);
    let client = StakingClient::new(&env, &contract_id);

    let result = client.try_unstake(&user, &1);
    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
}

#[test]
fn stake_and_unstake_reject_non_positive_amounts() {
    let (env, contract_id, _token_id, user) = setup(1_000);
    let client = StakingClient::new(&env, &contract_id);

    assert_eq!(client.try_stake(&user, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(client.try_unstake(&user, &-5), Err(Ok(Error::InvalidAmount)));
}

#[test]
fn stakes_are_tracked_per_user() {
    let (env, contract_id, token_id, user) = setup(1_000);
    let other = Address::generate(&env);
    token::StellarAssetClient::new(&env, &token_id).mint(&other, &500);
    let client = StakingClient::new(&env, &contract_id);

    client.stake(&user, &100);
    client.stake(&other, &50);

    assert_eq!(client.staked(&user), 100);
    assert_eq!(client.staked(&other), 50);
    assert_eq!(client.total_staked(), 150);
}
EOF
cd .. && cd .. && cargo test --manifest-path contracts/Cargo.toml -p staking 2>&1 | tail -40

